setup:
CREATE TABLE parcels AS SELECT * FROM (VALUES
  (1, ST_GeomFromText('POLYGON((0 0, 6 0, 0 8, 0 0))')),
  (2, ST_GeomFromText('POLYGON((0 0, 10 0, 10 10, 0 10, 0 0))'))
) t(parcel_id, geom);

solution:
LOAD spatial;

SELECT parcel_id,
       ROUND(ST_Perimeter(geom), 2) AS perimeter
FROM parcels
ORDER BY perimeter DESC;
